final class CaseMaterialRequestsTabController {
    private static final Logger LOG=LoggerFactory.getLogger(CaseMaterialRequestsTabController.class); private static final DateTimeFormatter F=DateTimeFormatter.ofPattern("MMM d, yyyy h:mm a");
    private final ExecutorService ex=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"case-material-requests-worker");t.setDaemon(true);return t;}); private final AtomicInteger gen=new AtomicInteger();
    private MaterialRequestServicePort svc; private AppState state; private Supplier<Long> caseId; private Supplier<Window> owner; private VBox root,list; private Label title,status; private boolean loaded;
    void init(MaterialRequestServicePort s, AppState a, Supplier<Long> c, Supplier<Window> o){svc=s;state=a;caseId=c;owner=o;}
    Node view(){ if(root!=null)return root; list=new VBox(10); title=title("Material Requests"); status=muted("Loading material requests…"); Button add=primary("New Request"); add.setOnAction(e->openNewRequestWindow()); root=new VBox(10,section(title,add,status,list)); root.setPadding(new Insets(8)); root.getStyleClass().add("case-main-surface"); return root; }
    void load(){ if(!loaded) refresh(); } void refresh(){ long cid=cid(); int tid=tenant(); int g=gen.incrementAndGet(); show(status,"Loading material requests…"); list.getChildren().clear(); runRead("list-material-requests",()->svc.listMaterialRequests(cid,tid), rows->{ if(stale(g,cid))return; loaded=true; render(rows==null?List.of():rows);}, "Material requests could not be loaded."); }
    private void render(List<MaterialRequestSummaryDto> rows){ var sorted=rows.stream().sorted(Comparator.comparing((MaterialRequestSummaryDto r)->terminal(r.status())).thenComparing(r->Optional.ofNullable(r.nextFollowUpAt()).orElse(Optional.ofNullable(r.expectedResponseDate()).orElse(LocalDateTime.MAX))).thenComparingLong(MaterialRequestSummaryDto::id)).toList(); title.setText("Material Requests ("+sorted.size()+")"); list.getChildren().clear(); if(sorted.isEmpty())show(status,"No material requests yet."); else {hide(status); sorted.forEach(r->list.getChildren().add(card(r)));}}
    private Node card(MaterialRequestSummaryDto r){ VBox b=MaterialsUi.card(); b.getChildren().addAll(strong(nvl(r.title(),r.materialTypeName())), pill("Status: "+nvl(r.status(),"Unknown")), line("From",source(r.requestedFromContactDisplayName(),r.requestedFromOrganizationName(),r.requestedFromText())), line("Assigned",nvl(r.assignedToDisplayName(),"Unassigned")), line("Requested / Due / Follow-up",fmt(r.requestedAt())+" • Due "+fmt(r.expectedResponseDate())+" • Next "+fmt(r.nextFollowUpAt()))); b.setOnMouseClicked(e->openDetail(r.id())); return b; }
    private void openNewRequestWindow(){ Stage stage=AppDialogs.createModalStage(owner.get(),"New Request"); VBox body=newRequestBody(stage); VBox root=AppDialogs.createSecondaryWindowShell(stage,"New Request",stage::close,body); VBox.setVgrow(body,Priority.ALWAYS); root.setPrefSize(520,360); root.setMinSize(420,260); Scene scene=new Scene(root); scene.getStylesheets().add(Objects.requireNonNull(CaseMaterialRequestsTabController.class.getResource("/css/app.css")).toExternalForm()); stage.setScene(scene); stage.setWidth(520); stage.setHeight(360); stage.showAndWait(); }
    VBox newRequestBody(Stage stage){ TextField titleField=new TextField(); titleField.setPromptText("New Request"); titleField.setMaxWidth(Double.MAX_VALUE); ComboBox<RequestMethodDto> requestMethod=lookupCombo(RequestMethodDto::name); requestMethod.setPromptText("Select request method"); ComboBox<RequestStatusDto> requestStatus=lookupCombo(RequestStatusDto::name); requestStatus.setPromptText("Select status"); loadNewRequestLookups(requestMethod,requestStatus,stage); GridPane fields=grid(); add(fields,0,"Title:",titleField); add(fields,1,"Request Method:",requestMethod); add(fields,2,"Status:",requestStatus); GridPane.setHgrow(titleField,Priority.ALWAYS); GridPane.setHgrow(requestMethod,Priority.ALWAYS); GridPane.setHgrow(requestStatus,Priority.ALWAYS); Region spacer=new Region(); VBox.setVgrow(spacer,Priority.ALWAYS); Button save=ActionButtonFactory.primary("Save",e->{ }); Button cancel=ActionButtonFactory.neutral("Cancel",e->{ if(confirmDiscardNewRequest(stage))stage.close(); }); HBox footer=new HBox(10,save,cancel); footer.getStyleClass().add("app-dialog-actions"); footer.setAlignment(Pos.CENTER_RIGHT); VBox body=new VBox(18,fields,spacer,footer); body.setPadding(new Insets(18)); body.setMaxWidth(Double.MAX_VALUE); return body; }
    private void loadNewRequestLookups(ComboBox<RequestMethodDto> requestMethod,ComboBox<RequestStatusDto> requestStatus,Window dialogOwner){ requestMethod.setDisable(true); requestStatus.setDisable(true); int tid=tenant(); ex.submit(()->{try{List<RequestMethodDto> methods=svc.listEffectiveRequestMethods(tid);List<RequestStatusDto> statuses=svc.listEffectiveRequestStatuses(tid);Platform.runLater(()->{requestMethod.getItems().setAll(methods==null?List.of():methods);requestStatus.getItems().setAll(statuses==null?List.of():statuses);selectRequestedStatus(requestStatus);requestMethod.setDisable(false);requestStatus.setDisable(false);});}catch(Exception x){LOG.warn("New Material Request lookup failed tenantId={}",tid,x);Platform.runLater(()->AppDialogs.showError(dialogOwner,"Requests","Request choices could not be loaded. Please try again."));}}); }
    private static void selectRequestedStatus(ComboBox<RequestStatusDto> requestStatus){ requestStatus.getSelectionModel().clearSelection(); requestStatus.getItems().stream().filter(s->s!=null&&"requested".equalsIgnoreCase(s.systemKey())).findFirst().ifPresent(requestStatus.getSelectionModel()::select); }
    private static <T> ComboBox<T> lookupCombo(java.util.function.Function<T,String> name){ ComboBox<T> combo=new ComboBox<>(); combo.setMaxWidth(Double.MAX_VALUE); combo.setConverter(new javafx.util.StringConverter<>(){public String toString(T value){return value==null?"":nvl(name.apply(value),"");}public T fromString(String s){return null;}}); return combo; }
    boolean confirmDiscardNewRequest(Window dialogOwner){ return AppDialogs.showChoice(dialogOwner,"Discard New Request?","Discard New Request?","Any information entered in this request will be lost.",List.of(AppDialogs.DialogAction.of("Discard",true,AppDialogs.DialogActionKind.DANGER,true,false),AppDialogs.DialogAction.cancel("Keep Editing",false))).orElse(false); }
    private void openDetail(long id){ long c=cid(); int t=tenant(), a=actor(); runRead("get-material-request",()->svc.getMaterialRequest(c,id,t,a).orElseThrow(),this::detail,"Material request could not be loaded."); }
    private void detail(MaterialRequestDetailDto d){ Dialog<Void> dlg=dialog("Material Request"); VBox c=new VBox(10,strong(nvl(d.title(),d.materialTypeName())),line("Status",nvl(d.status(),"Unknown")),line("Source",source(d.requestedFromContactDisplayName(),d.requestedFromOrganizationName(),d.requestedFromText())),line("Dates",fmt(d.requestedAt())+" • Due "+fmt(d.expectedResponseDate())+" • Follow-up "+fmt(d.nextFollowUpAt())),text("Description",d.description()),text("Notes",d.notes())); dlg.getDialogPane().getButtonTypes().addAll(ButtonType.CLOSE); dlg.getDialogPane().setContent(new ScrollPane(c)); dlg.showAndWait(); }
    private <T>void runRead(String op,Supplier<T>w,java.util.function.Consumer<T>ok,String msg){ ex.submit(()->{try{T t=w.get();Platform.runLater(()->ok.accept(t));}catch(Exception x){LOG.warn("Case Materials read failed op={} caseId={} generation={}",op,cid(),gen.get(),x);Platform.runLater(()->showInlineError(msg));}});} private void showInlineError(String m){list.getChildren().clear(); Button r=new Button("Retry"); r.setOnAction(e->refresh()); show(status,m); list.getChildren().add(r); AppDialogs.showError(owner.get(),"Requests",m);} private boolean stale(int g,long c){return g!=gen.get()||cid()!=c;} private long cid(){return caseId.get();} private int tenant(){return state.getShaleClientId();} private int actor(){Integer i=state.getUserId();return i==null?0:i;}
    private static boolean terminal(String s){return Set.of("CLOSED","CANCELLED","FULLY_RECEIVED").contains(nvl(s,"").toUpperCase(Locale.ROOT));}
}

final class CaseMaterialItemsTabController {
    private static final Logger LOG=LoggerFactory.getLogger(CaseMaterialItemsTabController.class); private final ExecutorService ex=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"case-material-items-worker");t.setDaemon(true);return t;}); private final AtomicInteger gen=new AtomicInteger(); private final AtomicInteger requestChoiceGen=new AtomicInteger(); private final AtomicBoolean saving=new AtomicBoolean(); private MaterialRequestServicePort req; private MaterialItemServicePort svc; private AppState state; private Supplier<Long> caseId; private Supplier<Window> owner; private VBox root,list; private Label title,status; private volatile List<MaterialRequestSummaryDto> activeRequests=List.of(); private boolean loaded;
    void init(MaterialRequestServicePort r,MaterialItemServicePort s,AppState a,Supplier<Long> c,Supplier<Window> o){req=r;svc=s;state=a;caseId=c;owner=o;} Node view(){if(root!=null)return root; list=new VBox(10); title=title("Case Materials"); status=muted("Loading case materials…"); Button add=primary("New Material"); add.setOnAction(e->openEditor(null)); root=new VBox(10,section(title,add,status,list)); root.setPadding(new Insets(8)); root.getStyleClass().add("case-main-surface"); return root;} void load(){if(!loaded)refresh();} void refresh(){long c=cid();int t=tenant();int g=gen.incrementAndGet();show(status,"Loading case materials…");list.getChildren().clear();runRead("list-material-items",()->svc.listMaterialItems(c,t), rows->{if(stale(g,c))return;loaded=true;render(rows==null?List.of():rows);},"Case materials could not be loaded.");}
    private void render(List<MaterialItemSummaryDto> rows){var sorted=rows.stream().sorted(Comparator.comparing((MaterialItemSummaryDto i)->Optional.ofNullable(i.receivedAt()).orElse(LocalDateTime.MIN),Comparator.reverseOrder()).thenComparing(i->nvl(i.name(),""),String.CASE_INSENSITIVE_ORDER)).toList(); title.setText("Case Materials ("+sorted.size()+")"); list.getChildren().clear(); if(sorted.isEmpty())show(status,"No case materials yet."); else{hide(status);sorted.forEach(i->list.getChildren().add(card(i)));}}
    private Node card(MaterialItemSummaryDto i){VBox b=MaterialsUi.card();b.getChildren().addAll(strong(nvl(i.name(),i.materialTypeName())),pill("Custody: "+nvl(i.custodyStatus(),"Unknown")),line("Format",nvl(i.format(),"Unknown")+" • "+nvl(i.completeness(),"Completeness unknown")),line("Received",fmt(i.receivedAt())+" by "+nvl(i.receivedByDisplayName(),"Unknown")),line("Counts","Qty "+val(i.quantityCount())+" • Pages "+val(i.pageCount())+" • Files "+val(i.fileCount())+(i.materialRequestId()!=null?" • Linked to request":" • No request link"))); b.setOnMouseClicked(e->openDetail(i.id()));return b;}
    private void openDetail(long id){runRead("get-material-item",()->svc.getMaterialItem(cid(),id,tenant(),actor()).orElseThrow(),this::detail,"Case material could not be loaded.");} private void detail(MaterialItemDetailDto d){Dialog<Void> dlg=dialog("Case Material"); VBox c=new VBox(10,strong(nvl(d.name(),d.materialTypeName())),line("Type / format",d.materialTypeName()+" • "+nvl(d.format(),"Unknown")),line("Source",source(d.sourceContactDisplayName(),d.sourceOrganizationName(),d.sourceText())),line("Coverage",fmt(d.relevantStartDate())+" to "+fmt(d.relevantEndDate())),line("Location/reference",nvl(d.storageLocation(),"Not provided")+(d.externalLinkId()!=null?" • ExternalLink reference":"")),line("Custody",nvl(d.custodyStatus(),"Unknown")),text("Description",d.description()),text("Physical condition",d.physicalCondition()),text("Return/release notes",d.returnReleaseNotes())); ButtonType edit=new ButtonType("Edit Metadata"),link=new ButtonType("Link/Unlink Request"),loc=new ButtonType("Location/Reference"),rel=new ButtonType("Record Return/Release"),del=new ButtonType("Delete",ButtonBar.ButtonData.LEFT); dlg.getDialogPane().getButtonTypes().addAll(edit,link,loc,rel,del,ButtonType.CLOSE); dlg.getDialogPane().setContent(new ScrollPane(c)); button(dlg,edit,()->openEditor(d)); button(dlg,link,()->link(d)); button(dlg,loc,()->loc(d)); button(dlg,rel,()->release(d)); button(dlg,del,()->del(d)); dlg.showAndWait();}
    private void openEditor(MaterialItemDetailDto e){List<MaterialRequestSummaryDto> choices=requestChoicesOrShowError(); if(choices==null)return; MaterialItemForm f=new MaterialItemForm(e,req.listEffectiveMaterialTypes(tenant()),choices,actor());f.showAndWait().ifPresent(v->mutate(()->e==null?svc.createMaterialItem(v.create(tenant(),actor(),cid())):svc.updateMaterialItem(v.update(tenant(),actor(),cid(),e.id(),e.rowVer())),this::refresh,"Material item saved."));}
    private void link(MaterialItemDetailDto d){ if(d.materialRequestId()!=null)mutate(()->svc.unlinkMaterialItemFromRequest(new MaterialItemServicePort.UnlinkMaterialItemFromRequestCommand(tenant(),actor(),cid(),d.id(),d.rowVer())),this::refresh,"Request link removed."); else {List<MaterialRequestSummaryDto> choices=requestChoicesOrShowError(); if(choices!=null&&!choices.isEmpty())mutate(()->svc.linkMaterialItemToRequest(new MaterialItemServicePort.LinkMaterialItemToRequestCommand(tenant(),actor(),cid(),d.id(),choices.get(0).id(),d.rowVer())),this::refresh,"Request linked.");}}
    private void loc(MaterialItemDetailDto d){TextInputDialog t=new TextInputDialog(nvl(d.storageLocation(),""));t.setTitle("Location/reference metadata");t.setHeaderText("Metadata only. No upload, download, file chooser, attachment, image text extraction, blob-storage, or file storage occurs.");t.showAndWait().ifPresent(s->mutate(()->svc.changeMaterialItemLocation(new MaterialItemServicePort.ChangeMaterialItemLocationCommand(tenant(),actor(),cid(),d.id(),trim(s),d.externalLinkId(),d.rowVer())),this::refresh,"Location metadata updated."));} private void release(MaterialItemDetailDto d){ChoiceDialog<String> c=new ChoiceDialog<>("RETURNED",List.of("RETURNED","RELEASED","DESTROYED"));c.setTitle("Record Return/Release");c.showAndWait().ifPresent(s->mutate(()->svc.releaseOrReturnMaterialItem(new MaterialItemServicePort.ReleaseOrReturnMaterialItemCommand(tenant(),actor(),cid(),d.id(),s,LocalDateTime.now(),null,null,"recipient","HAND_DELIVERY",null,d.rowVer())),this::refresh,"Return/release recorded."));} private void del(MaterialItemDetailDto d){mutate(()->{svc.softDeleteMaterialItem(new MaterialItemServicePort.SoftDeleteMaterialItemCommand(tenant(),actor(),cid(),d.id(),d.rowVer()));return null;},this::refresh,"Material item deleted.");}

    private List<MaterialRequestSummaryDto> requestChoicesOrShowError(){long c=cid();int t=tenant();int g=requestChoiceGen.incrementAndGet();try{List<MaterialRequestSummaryDto> choices=req.listMaterialRequests(c,t).stream().filter(r->!Set.of("CLOSED","CANCELLED").contains(nvl(r.status(),"").toUpperCase(Locale.ROOT))).toList();if(g==requestChoiceGen.get()&&cid()==c)activeRequests=choices;return choices;}catch(Exception x){LOG.warn("Case Materials auxiliary lookup failed op=list-material-request-choices caseId={} generation={}",c,g,x);AppDialogs.showError(owner.get(),"Case Materials","Material request choices could not be loaded. Please retry before linking a request.");return null;}}
    private <T>void runRead(String op,Supplier<T>w,java.util.function.Consumer<T>ok,String msg){ex.submit(()->{try{T t=w.get();Platform.runLater(()->ok.accept(t));}catch(Exception x){LOG.warn("Case Materials read failed op={} caseId={} generation={}",op,cid(),gen.get(),x);Platform.runLater(()->{list.getChildren().clear();Button r=new Button("Retry");r.setOnAction(e->refresh());show(status,msg);list.getChildren().add(r);AppDialogs.showError(owner.get(),"Case Materials",msg);});}});} private <T>void mutate(Supplier<T>w,Runnable after,String msg){if(!saving.compareAndSet(false,true))return;ex.submit(()->{try{w.get();Platform.runLater(()->{saving.set(false);after.run();AppDialogs.showInfo(owner.get(),"Case Materials",msg);});}catch(Exception x){LOG.warn("Case material item mutation failed caseId={}",cid(),x);Platform.runLater(()->{saving.set(false);AppDialogs.showError(owner.get(),"Case Materials","The case material could not be saved. Please review the fields and try again.");});}});} private boolean stale(int g,long c){return g!=gen.get()||cid()!=c;} private long cid(){return caseId.get();} private int tenant(){return state.getShaleClientId();} private int actor(){Integer i=state.getUserId();return i==null?0:i;}
}

final class MaterialItemForm extends Dialog<MaterialItemForm.Values>{record Values(Long requestId,int type,String format,String name,String description,Integer contact,Integer org,String sourceText,int receivedBy,LocalDateTime receivedAt,LocalDate start,LocalDate end,String completeness,Integer qty,Integer pages,Integer files,String storage,Integer externalLink,String condition,String custody){MaterialItemServicePort.CreateMaterialItemCommand create(int t,int a,long c){return new MaterialItemServicePort.CreateMaterialItemCommand(t,a,c,requestId,type,format,name,description,contact,org,sourceText,receivedBy,receivedAt,start,end,completeness,qty,pages,files,storage,externalLink,condition,custody);} MaterialItemServicePort.UpdateMaterialItemCommand update(int t,int a,long c,long id,byte[] rv){return new MaterialItemServicePort.UpdateMaterialItemCommand(t,a,c,id,type,format,name,description,contact,org,sourceText,start,end,completeness,qty,pages,files,condition,rv);}} MaterialItemForm(MaterialItemDetailDto e,List<MaterialTypeDto> types,List<MaterialRequestSummaryDto> reqs,int actor){setTitle(e==null?"New Material":"Edit Material Metadata"); ComboBox<MaterialTypeDto> type=new ComboBox<>();type.getItems().setAll(types);type.setConverter(new javafx.util.StringConverter<>(){public String toString(MaterialTypeDto x){return x==null?"":x.name();}public MaterialTypeDto fromString(String s){return null;}}); if(e!=null)type.getSelectionModel().select(types.stream().filter(x->x.id()==e.materialTypeId()).findFirst().orElse(null));else type.getSelectionModel().selectFirst(); ComboBox<MaterialRequestSummaryDto> rq=new ComboBox<>();rq.getItems().setAll(reqs);rq.setConverter(new javafx.util.StringConverter<>(){public String toString(MaterialRequestSummaryDto x){return x==null?"No linked request":nvl(x.title(),"Request #"+x.id());}public MaterialRequestSummaryDto fromString(String s){return null;}}); if(e!=null)rq.getSelectionModel().select(reqs.stream().filter(x->Objects.equals(x.id(),e.materialRequestId())).findFirst().orElse(null)); TextField name=new TextField(e==null?"":nvl(e.name(),"")),format=new TextField(e==null?"PAPER":nvl(e.format(),"")),contact=new TextField(e==null?"":val(e.sourceContactId())),org=new TextField(e==null?"":val(e.sourceOrganizationId())),qty=new TextField(e==null?"":val(e.quantityCount())),pages=new TextField(e==null?"":val(e.pageCount())),files=new TextField(e==null?"":val(e.fileCount())),storage=new TextField(e==null?"":nvl(e.storageLocation(),"")),external=new TextField(e==null?"":val(e.externalLinkId())),condition=new TextField(e==null?"":nvl(e.physicalCondition(),"")); TextArea desc=new TextArea(e==null?"":nvl(e.description(),"")),source=new TextArea(e==null?"":nvl(e.sourceText(),"")); DatePicker rec=new DatePicker(e==null?LocalDate.now():toDate(e.receivedAt())),start=new DatePicker(e==null?null:e.relevantStartDate()),end=new DatePicker(e==null?null:e.relevantEndDate()); ChoiceBox<String> comp=new ChoiceBox<>();comp.getItems().setAll("UNKNOWN","COMPLETE","PARTIAL");comp.setValue(nvl(e==null?null:e.completeness(),"UNKNOWN")); ChoiceBox<String> custody=new ChoiceBox<>();custody.getItems().setAll("IN_FIRM_CUSTODY","RETURNED","RELEASED");custody.setValue(nvl(e==null?null:e.custodyStatus(),"IN_FIRM_CUSTODY")); GridPane g=grid();int r=0;add(g,r++,"Identity: Material Type *",type);add(g,r++,"Identity: Name *",name);add(g,r++,"Identity: Format *",format);add(g,r++,"Optional associated Material Request",rq);add(g,r++,"Source Contact selector",contact);add(g,r++,"Source Organization selector",org);add(g,r++,"Controlled free-text source",source);add(g,r++,"Received-by user *",new Label("Current user #"+actor));add(g,r++,"Received date/time *",rec);add(g,r++,"Relevant start",start);add(g,r++,"Relevant end",end);add(g,r++,"Completeness",comp);add(g,r++,"Quantity count",qty);add(g,r++,"Page count",pages);add(g,r++,"File count",files);add(g,r++,"Storage location (not a file upload)",storage);add(g,r++,"ExternalLink reference selector",external);add(g,r++,"Physical condition",condition);add(g,r++,"Initial custody status",custody);add(g,r++,"Description",desc);getDialogPane().setContent(new ScrollPane(g));getDialogPane().getButtonTypes().addAll(ButtonType.OK,ButtonType.CANCEL);setResultConverter(bt->bt==ButtonType.OK?new Values(rq.getValue()==null?null:rq.getValue().id(),type.getValue().id(),trim(format.getText()),trim(name.getText()),trim(desc.getText()),num(contact),num(org),trim(source.getText()),actor,at(rec.getValue()),start.getValue(),end.getValue(),comp.getValue(),nonneg(qty),nonneg(pages),nonneg(files),trim(storage.getText()),num(external),trim(condition.getText()),custody.getValue()):null);} }

final class MaterialsUi { private MaterialsUi(){}
    static Label title(String s){Label l=new Label(s);l.setStyle("-fx-font-size:16px;-fx-font-weight:bold;");return l;} static Label strong(String s){Label l=new Label(s);l.setStyle("-fx-font-weight:bold;");l.setWrapText(true);return l;} static Label muted(String s){Label l=new Label(s);l.setStyle("-fx-opacity:.75;");l.setWrapText(true);return l;} static Label pill(String s){Label l=new Label(s);l.getStyleClass().add("shale-status-pill");return l;} static Label line(String k,String v){Label l=new Label(k+": "+v);l.setWrapText(true);return l;} static Label text(String k,String v){return line(k,nvl(v,"Not provided"));} static Button primary(String s){return ActionButtonFactory.primary(s,null);} static VBox card(){VBox v=new VBox(6);v.setPadding(new Insets(10));v.getStyleClass().addAll("shale-card","entity-card");return v;} static VBox section(Label t,Button b,Label s,VBox list){HBox h=new HBox(8,t,new Region(),b);HBox.setHgrow(h.getChildren().get(1),Priority.ALWAYS);h.setAlignment(Pos.CENTER_LEFT);ScrollPane sp=new ScrollPane(list);sp.setFitToWidth(true);VBox v=new VBox(10,h,s,sp);VBox.setVgrow(sp,Priority.ALWAYS);v.setPadding(new Insets(10));v.getStyleClass().add("shale-surface-section");return v;} static VBox section(Label t,Label s,VBox list){ScrollPane sp=new ScrollPane(list);sp.setFitToWidth(true);VBox v=new VBox(10,t,s,sp);VBox.setVgrow(sp,Priority.ALWAYS);v.setPadding(new Insets(10));v.getStyleClass().add("shale-surface-section");return v;} static void show(Label l,String s){l.setText(s);l.setVisible(true);l.setManaged(true);} static void hide(Label l){l.setVisible(false);l.setManaged(false);} static Dialog<Void> dialog(String t){Dialog<Void>d=new Dialog<>();d.setTitle(t);d.getDialogPane().setPrefSize(720,620);return d;} static void button(Dialog<?>d,ButtonType t,Runnable r){Node n=d.getDialogPane().lookupButton(t);n.addEventFilter(javafx.event.ActionEvent.ACTION,e->{e.consume();r.run();});} static String trim(String s){return s==null?null:s.trim();} static String nvl(String s,String v){return s==null||s.isBlank()?v:s;} static String fmt(LocalDateTime t){return t==null?"Not set":t.format(DateTimeFormatter.ofPattern("MMM d, yyyy h:mm a"));} static String fmt(LocalDate d){return d==null?"Not set":d.toString();} static String source(String c,String o,String t){return nvl(c,nvl(o,nvl(t,"Not provided")));} static String val(Object o){return o==null?"—":o.toString();} static Integer num(TextField f){try{String s=f.getText();return s==null||s.isBlank()?null:Integer.valueOf(s.trim());}catch(Exception e){return null;}} static Integer nonneg(TextField f){Integer n=num(f);return n==null?null:Math.max(0,n);} static LocalDateTime at(LocalDate d){return d==null?null:d.atStartOfDay();} static LocalDate toDate(LocalDateTime d){return d==null?null:d.toLocalDate();} static GridPane grid(){GridPane g=new GridPane();g.setHgap(10);g.setVgap(8);g.setPadding(new Insets(12));return g;} static void add(GridPane g,int r,String label,Node n){g.add(new Label(label),0,r);g.add(n,1,r);}
}
